/**
 * 用户注意力（User Attention）— Host half。
 *
 * 把「用户此刻是否在 DSH 网页界面旁」建模为三态：online（在线）/ away（暂离）/
 * offline（离线），并据此决定 AI 触发的人类交互（approval 批准、ask_user_question
 * 提问）该如何处理：
 *
 *   online  — 完全照常：直接交给下游应答者（浏览器交互 UI）。
 *             浏览器侧的活动上报驱动状态；超过 idleTimeoutMs 没有鼠标/键盘活动
 *             就自动降为 away。
 *   away    — 交互照常呈现给用户；若在 awayRetryIntervalMs 内没有回应，就通过
 *             浏览器提醒（横幅 + 提示音）再尝试 awayRetryCount 次，期间不返回给
 *             AI；仍然无人处理则向 AI 说明原因、自动拒绝该交互并降为 offline。
 *   offline — 所有人类交互立即拒绝并向 AI 说明；浏览器检测到鼠标/键盘活动后
 *             自动恢复 online。
 *
 * Host 侧实现要点：
 *   - 通过 `ctx.on('approval/request' | 'user-questions/request', ..., { prepend: true })`
 *     抢在下游（浏览器 Remote 应答者）之前执行门控。
 *   - 通过 `ctx.connection.fetch.register` 注册同源、经应用鉴权栅栏的 /api 路由，
 *     供 Client 半身上报活动、轮询状态、手动切换状态。
 *   - 通过 `ctx.systemPrompt.context` 把当前注意力状态作为运行时上下文告诉模型，
 *     并在自动拒绝时用 `agent.inject` 注入一条可回放的说明消息（用户可见）。
 *   - 本组件随 bundle @local/dsh-user-attention-and-todo-inbox 一起安装（嵌套在
 *     该包 node_modules 里）：不 import 任何 @deepseek-ai/* 包，全部依赖从 ctx 取。
 */

import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'

/** 配置默认值；所有字段都可在 profile 补丁的本行 config 里覆盖。 */
const DEFAULT_CONFIG = {
  idleTimeoutMs: 300000,
  awayRetryCount: 2,
  awayRetryIntervalMs: 30000,
  tickMs: 5000,
  pollIntervalMs: 1500,
  initialState: 'online',
  persistManualState: true,
  approvalTimeoutAction: 'reject',
  questionTimeoutAction: 'reject',
  preferRecommended: false,
  todoAutoEnqueue: true,
}

/** 超时策略：拒绝，或拒绝并加入待办。 */
export const TIMEOUT_ACTIONS = ['reject', 'enqueue']

/**
 * DSH 原生的问题选项“推荐”标记：`Approve (Recommended)` / `同意（推荐）`。
 * 与 `dsh-client-ui-user-questions` 的 parseRecommendedLabel 保持同一规则。
 */
export const RECOMMENDED_LABEL_SUFFIX = /\s*(?:\((?:recommended|推荐)\)|（(?:recommended|推荐)）)\s*$/i

/** 在问题批次里按原生规则找推荐项：每个问题第一个带推荐后缀的选项。 */
export function buildRecommendedAnswer(questions) {
  if (!Array.isArray(questions) || questions.length === 0) return null
  const answers = []
  for (const question of questions) {
    if (question === null || typeof question !== 'object') return null
    const id = typeof question.id === 'string' ? question.id : ''
    if (id === '') return null
    const options = Array.isArray(question.options) ? question.options : []
    const recommended = options.find((option) =>
      option !== null && option !== undefined && typeof option.label === 'string' &&
      RECOMMENDED_LABEL_SUFFIX.test(option.label))
    if (recommended === undefined) return null
    answers.push({ id, selected: [recommended.label] })
  }
  return answers.length === questions.length ? { answers } : null
}

const STATES = ['online', 'away', 'offline']

/** 浏览器活动上报允许的类型；其他值不改变注意力状态（防止鉴权后误发/畸形请求）。 */
const ACTIVITY_KINDS = new Set(['pointermove', 'pointerdown', 'keydown', 'wheel', 'touchstart', 'focus', 'visible'])


/** 把任意用户配置收敛成安全值（不信任 YAML 里的类型）。 */
export function normalizeConfig(raw) {
  const input = raw !== null && typeof raw === 'object' ? raw : {}
  const number = (value, fallback, min, max) => {
    const n = Number(value)
    if (!Number.isFinite(n)) return fallback
    return Math.min(max, Math.max(min, n))
  }
  const integer = (value, fallback, min, max) => Math.round(number(value, fallback, min, max))
  return {
    idleTimeoutMs: integer(input.idleTimeoutMs, DEFAULT_CONFIG.idleTimeoutMs, 1000, 24 * 3600 * 1000),
    awayRetryCount: integer(input.awayRetryCount, DEFAULT_CONFIG.awayRetryCount, 0, 5),
    awayRetryIntervalMs: integer(input.awayRetryIntervalMs, DEFAULT_CONFIG.awayRetryIntervalMs, 2000, 600000),
    tickMs: integer(input.tickMs, DEFAULT_CONFIG.tickMs, 1000, 60000),
    pollIntervalMs: integer(input.pollIntervalMs, DEFAULT_CONFIG.pollIntervalMs, 500, 10000),
    initialState: STATES.includes(input.initialState) ? input.initialState : DEFAULT_CONFIG.initialState,
    persistManualState: typeof input.persistManualState === 'boolean'
      ? input.persistManualState
      : DEFAULT_CONFIG.persistManualState,
    approvalTimeoutAction: TIMEOUT_ACTIONS.includes(input.approvalTimeoutAction)
      ? input.approvalTimeoutAction
      : DEFAULT_CONFIG.approvalTimeoutAction,
    questionTimeoutAction: TIMEOUT_ACTIONS.includes(input.questionTimeoutAction)
      ? input.questionTimeoutAction
      : DEFAULT_CONFIG.questionTimeoutAction,
    preferRecommended: input.preferRecommended === true,
    todoAutoEnqueue: typeof input.todoAutoEnqueue === 'boolean' ? input.todoAutoEnqueue : DEFAULT_CONFIG.todoAutoEnqueue,
    // 可选的 Harness home 覆盖；空白字符串视为未设置。
    home: typeof input.home === 'string' && input.home.trim() !== '' ? input.home : undefined,
  }
}

function uuid() {
  try {
    if (typeof globalThis.crypto?.randomUUID === 'function') return globalThis.crypto.randomUUID()
  } catch (error) { /* 回退到时间戳形式 */ }
  return 'ua-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10)
}

function jsonResponse(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
    },
  })
}

function normalizeKind(kind) {
  return kind === 'question' ? 'question' : 'approval'
}

function interactionLabel(kind) {
  return normalizeKind(kind) === 'question' ? '提问（ask_user_question）' : '批准（approval）'
}

/** 最终拒绝事件的版本号；待办收件箱等消费者据此判断字段是否兼容。 */
export const ATTENTION_REJECTION_VERSION = 1

/** 拒绝事件里携带的问题上限：问题正文可能包含很长的计划 markdown，必须截断。 */
export const ATTENTION_QUESTION_LIMITS = Object.freeze({
  questions: 10,
  questionChars: 2000,
  detailChars: 4000,
  headerChars: 200,
  optionLabelChars: 200,
  optionDescriptionChars: 500,
  options: 20,
})

/** 截断任意文本字段；非字符串一律视为空。 */
function boundText(value, max) {
  return typeof value === 'string' ? value.slice(0, max) : ''
}

/**
 * 把 ask_user_question 的原始问题数组收敛成 wire 安全的副本。
 * 只保留待办收件箱渲染/回答所需的字段，并给每个字段设上限。
 */
export function sanitizeQuestions(raw) {
  if (!Array.isArray(raw)) return []
  const output = []
  for (const item of raw.slice(0, ATTENTION_QUESTION_LIMITS.questions)) {
    if (item === null || typeof item !== 'object') continue
    const id = boundText(item.id, 120)
    const question = boundText(item.question, ATTENTION_QUESTION_LIMITS.questionChars)
    if (id === '' || question === '') continue
    const copy = { id, question }
    const detail = boundText(item.detail, ATTENTION_QUESTION_LIMITS.detailChars)
    if (detail !== '') copy.detail = detail
    const header = boundText(item.header, ATTENTION_QUESTION_LIMITS.headerChars)
    if (header !== '') copy.header = header
    if (Array.isArray(item.options)) {
      const options = []
      for (const option of item.options.slice(0, ATTENTION_QUESTION_LIMITS.options)) {
        if (option === null || typeof option !== 'object') continue
        const label = boundText(option.label, ATTENTION_QUESTION_LIMITS.optionLabelChars)
        if (label === '') continue
        const next = { label }
        const description = boundText(option.description, ATTENTION_QUESTION_LIMITS.optionDescriptionChars)
        if (description !== '') next.description = description
        options.push(next)
      }
      if (options.length > 0) copy.options = options
    }
    if (item.multiSelect === true) copy.multiSelect = true
    const intent = item.intent
    if (intent !== null && intent !== undefined && typeof intent === 'object' && intent.kind === 'plan-review') {
      const approve = boundText(intent.approve, 200)
      if (approve !== '') {
        copy.intent = { kind: 'plan-review', approve }
        if (intent.callId !== undefined && intent.callId !== null) {
          copy.intent.callId = String(intent.callId).slice(0, 200)
        }
      }
    }
    output.push(copy)
  }
  return output
}

/**
 * 构造交给 `userAttention.onRejection()` 订阅者的最终拒绝事件。
 *
 * 只包含待办收件箱需要的字段：kind / reason / 会话身份 / 工具调用身份 /
 * 问题快照。调用参数不在事件里——待办按 sessionId + callId 从会话日志读取
 * 并做哈希校验，避免把完整参数复制进第二个持久化文件。
 *
 * @param kind - 'approval' | 'question'
 * @param req - 原始 approval / user-questions 请求对象
 * @param reason - 'manual' | 'offline' | 'timeout-manual' | 'timeout'
 * @param fallbackSessionId - 请求对象没带 agent 时由调用方补充的会话 id
 * @returns 可安全跨插件传递的普通对象（永不抛错）
 */
export function buildAttentionRejection(kind, req, reason, fallbackSessionId) {
  const normalizedKind = normalizeKind(kind)
  const request = req !== null && typeof req === 'object' ? req : {}
  const allowedReasons = new Set(['manual', 'offline', 'timeout-manual', 'timeout'])
  const event = {
    version: ATTENTION_REJECTION_VERSION,
    kind: normalizedKind,
    reason: allowedReasons.has(reason) ? reason : 'offline',
    at: Date.now(),
  }
  let sessionId = typeof fallbackSessionId === 'string' && fallbackSessionId !== '' ? fallbackSessionId : undefined
  try {
    const agent = request.agent
    if (agent !== null && agent !== undefined && agent.id !== undefined && agent.id !== null) {
      const candidate = String(agent.id)
      if (candidate !== '') sessionId = candidate
    }
  } catch (error) { /* req.agent 可能被冻结或不可读，回退到调用方提供的 id */ }
  if (sessionId !== undefined) event.sessionId = sessionId
  if (normalizedKind === 'approval') {
    const toolName = boundText(request.toolName, 160)
    if (toolName !== '') event.toolName = toolName
    if (request.callId !== undefined && request.callId !== null) {
      const callId = String(request.callId).slice(0, 200)
      if (callId !== '') event.callId = callId
    }
    const requestReason = boundText(request.reason, 500)
    if (requestReason !== '') event.requestReason = requestReason
  } else {
    try {
      const wait = request.wait
      if (wait !== null && wait !== undefined && typeof wait === 'object' && wait.callId !== undefined && wait.callId !== null) {
        const callId = String(wait.callId).slice(0, 200)
        if (callId !== '') event.callId = callId
      }
    } catch (error) { /* 缺失 wait 时问题待办仍可回答，只是不能定位原始工具调用 */ }
    const questions = sanitizeQuestions(request.questions)
    if (questions.length > 0) event.questions = questions
  }
  return event
}

export function apply(ctx, config) {
  const cfg = normalizeConfig(config)
  /** Host 半身本次激活的身份；Client 用它识别 alertSeq 纪元的重置（live reload 后）。 */
  const instanceId = uuid()

  const log = (...args) => {
    try { console.log('[user-attention]', ...args) } catch (error) { /* 日志不可用不影响功能 */ }
  }

  // ---------------------------------------------------------------------------
  // 手动状态持久化（A.4/A.5）
  //
  // 目录：<home>/.user-attention/state.json。home 优先级：
  //   config.home -> profileContext.home -> DSH_HOME -> ~/.dsh
  // 只恢复「人类手动选择的 away/offline」；损坏/缺失文件都被安全忽略。
  // ---------------------------------------------------------------------------
  function resolveHome() {
    if (cfg.home !== undefined) return cfg.home
    try {
      const profileContext = ctx.get('profileContext')
      if (profileContext !== null && typeof profileContext === 'object' &&
        typeof profileContext.home === 'string' && profileContext.home.trim() !== '') {
        return profileContext.home
      }
    } catch (error) { /* profileContext 不可用时继续回退 */ }
    const envHome = typeof process !== 'undefined' && process.env !== undefined ? process.env.DSH_HOME : undefined
    if (typeof envHome === 'string' && envHome.trim() !== '') return envHome
    return join(homedir(), '.dsh')
  }

  const home = resolveHome()
  const stateDir = join(home, '.user-attention')
  const stateFile = join(stateDir, 'state.json')

  function loadPersistedManualState() {
    if (!cfg.persistManualState) return null
    try {
      if (!existsSync(stateFile)) return null
      const parsed = JSON.parse(readFileSync(stateFile, 'utf8'))
      const valid = parsed !== null && typeof parsed === 'object' && parsed.version === 1 &&
        parsed.manual === true && (parsed.state === 'away' || parsed.state === 'offline')
      if (!valid) {
        log('ignoring malformed persisted state file:', stateFile)
        return null
      }
      return parsed.state
    } catch (error) {
      log('could not restore persisted state (ignored):', error && error.message)
      return null
    }
  }

  /** 先写临时文件再原子替换；Windows 上目标已存在时 rename 可能失败，回退为直接覆写。 */
  function persistManualState(next) {
    if (!cfg.persistManualState) return
    const payload = JSON.stringify({ version: 1, state: next, manual: true, savedAt: Date.now() })
    const tmpFile = stateFile + '.' + process.pid + '.' + Date.now() + '.tmp'
    try {
      mkdirSync(stateDir, { recursive: true })
      writeFileSync(tmpFile, payload, 'utf8')
      try {
        renameSync(tmpFile, stateFile)
      } catch (error) {
        if (!existsSync(stateFile)) throw error
        writeFileSync(stateFile, payload, 'utf8')
        try { rmSync(tmpFile, { force: true }) } catch (cleanupError) { /* 临时文件清理失败可忽略 */ }
      }
    } catch (error) {
      try { if (existsSync(tmpFile)) rmSync(tmpFile, { force: true }) } catch (cleanupError) { /* 同上 */ }
      // 持久化失败不影响本次状态切换，只记录日志。
      log('could not persist manual state:', error && error.message)
    }
  }

  function clearPersistedManualState() {
    try {
      rmSync(stateFile, { force: true })
    } catch (error) {
      log('could not clear persisted state:', error && error.message)
    }
  }

  // ---------------------------------------------------------------------------
  // 注意力状态（手动 away/offline 可跨重载恢复；initialState 仅在没有恢复时生效）
  // ---------------------------------------------------------------------------
  let state = cfg.initialState
  let since = Date.now()
  let lastActivityAt = since
  /**
   * true 表示当前非在线状态是「人类手动选择」的：冻结自动状态机
   * （活动不再自动恢复在线、暂离交互超时不再自动降级离线），直到手动切回在线。
   */
  let manualState = false
  const restoredManualState = loadPersistedManualState()
  if (restoredManualState !== null) {
    state = restoredManualState
    manualState = true
    log('restored manual state:', restoredManualState)
  }
  let alertSeq = 0
  let alert = null
  // A.1/A.2：被自动拒绝的人工交互摘要（内部最多 20 条，payload 只回传最近 5 条）。
  let rejectionSeq = 0
  let ackedThrough = 0
  let rejections = []
  /** userAttention 服务的订阅者：状态变化与最终拒绝事件。 */
  const stateListeners = new Set()
  const rejectionListeners = new Set()
  /** 正在等待人类回应的门控；手动切离线 / 插件卸载时用来立即收尾。 */
  const activeGates = new Set()
  /** 已呈现给用户、尚未结束的交互；保存配置前用来判断是否需要 force。 */
  const activeInteractions = new Set()
  let disposed = false

  function notifyState(previous, reason) {
    const payload = { previous, state, manual: manualState, since, lastActivityAt, reason }
    for (const listener of [...stateListeners]) {
      try {
        listener(payload)
      } catch (error) {
        log('state listener failed:', error && error.message)
      }
    }
  }

  function setState(next, reason) {
    if (!STATES.includes(next) || next === state) return
    const previous = state
    state = next
    since = Date.now()
    if (next === 'online') manualState = false
    log('state', previous, '->', next, '(' + reason + ')')
    notifyState(previous, reason)
  }

  function noteActivity(source) {
    lastActivityAt = Date.now()
    // 手动选择的非在线状态是「粘性」的：活动只刷新 lastActivityAt，不自动回到在线。
    if (state !== 'online' && !manualState) setState('online', 'activity:' + String(source))
  }

  function pushAlert(partial) {
    if (disposed) return null
    alertSeq += 1
    const now = Date.now()
    alert = {
      seq: alertSeq,
      kind: partial.kind,
      interaction: partial.interaction === undefined ? null : partial.interaction,
      attempt: partial.attempt === undefined ? null : partial.attempt,
      maxAttempts: partial.maxAttempts === undefined ? null : partial.maxAttempts,
      title: partial.title,
      body: partial.body,
      at: now,
      expiresAt: now + (partial.ttlMs === undefined ? 30000 : partial.ttlMs),
    }
    return alert
  }

  function rejectionsPayload() {
    return {
      seq: rejectionSeq,
      count: Math.max(0, rejectionSeq - ackedThrough),
      items: rejections.slice(-5).map((item) => ({ ...item })),
    }
  }

  function statePayload() {
    const now = Date.now()
    return {
      ok: true,
      version: 2,
      now,
      instanceId,
      state,
      manual: manualState,
      since,
      lastActivityAt,
      idleTimeoutMs: cfg.idleTimeoutMs,
      awayRetryIntervalMs: cfg.awayRetryIntervalMs,
      awayRetryCount: cfg.awayRetryCount,
      pollIntervalMs: cfg.pollIntervalMs,
      nextAwayAt: state === 'online' ? lastActivityAt + cfg.idleTimeoutMs : null,
      alertSeq,
      alert: alert === null ? null : { ...alert },
      rejections: rejectionsPayload(),
    }
  }

  // ---------------------------------------------------------------------------
  // 浏览器提醒
  // ---------------------------------------------------------------------------
  /** 所有最终拒绝都经 publishRejectedAlert 记录，保证摘要与拒绝行为一一对应。 */
  function recordRejection(kind, reason) {
    rejectionSeq += 1
    rejections.push({ seq: rejectionSeq, kind: normalizeKind(kind), reason, at: Date.now() })
    if (rejections.length > 20) rejections.splice(0, rejections.length - 20)
  }

  function publishRetryAlert(kind, attempt, maxAttempts) {
    const shown = Math.max(0, attempt - 1)
    const retries = Math.max(0, maxAttempts - 1)
    pushAlert({
      kind: 'interaction-retry',
      interaction: normalizeKind(kind),
      attempt,
      maxAttempts,
      title: '需要你的操作',
      body: 'AI 正在等待你的' + (normalizeKind(kind) === 'question' ? '回答' : '批准') +
        '，当前处于暂离状态。第 ' + shown + '/' + retries + ' 次提醒；' +
        (manualState
          ? '当前状态是手动设置的，移动鼠标不会自动恢复；请在状态胶囊里切回在线。'
          : '在页面内移动鼠标或按键可恢复在线。'),
      ttlMs: cfg.awayRetryIntervalMs + 20000,
    })
  }

  function publishRejectedAlert(kind, reason) {
    recordRejection(kind, reason)
    let body
    if (reason === 'manual') body = '你已切换到离线状态，未处理的人工交互被自动拒绝。'
    else if (reason === 'offline') body = '当前处于离线状态，本次人工交互被自动拒绝。'
    else if (reason === 'timeout-manual') body = '手动暂离且无人响应：本次人工交互被自动拒绝，状态保持手动暂离。'
    else if (cfg.awayRetryCount === 0) body = '当前处于暂离状态且未启用重试，本次人工交互被自动拒绝，状态转为离线。'
    else body = '多次提醒后仍无响应，已转为离线；本次人工交互被自动拒绝。'
    pushAlert({
      kind: 'interaction-rejected',
      interaction: normalizeKind(kind),
      title: '已自动拒绝人工交互',
      body,
      ttlMs: 60000,
    })
  }

  // ---------------------------------------------------------------------------
  // 模型可见的状态说明
  // ---------------------------------------------------------------------------
  function attentionPromptText() {
    if (state === 'offline') {
      return 'User attention: offline (离线). The user is not at the DSH Web interface. ' +
        'All human-interaction operations (approval prompts and ask_user_question) are auto-rejected immediately; ' +
        'do not rely on human input. Continue with work that needs no human input, and clearly state in your final reply ' +
        'anything that needs the user to decide when they return.' +
        (manualState
          ? ' This state was set MANUALLY by the user and is sticky: mouse/keyboard activity will NOT switch it back; ' +
            'only an explicit manual switch to online restores human interaction.'
          : '')
    }
    if (state === 'away') {
      if (manualState) {
        return 'User attention: away (暂离). This state was set MANUALLY by the user and is sticky: mouse and keyboard ' +
          'activity will NOT switch it back, and it will not auto-downgrade to offline. Human interactions are delivered ' +
          'with reminders; if no answer arrives after ' + cfg.awayRetryCount +
          ' retr' + (cfg.awayRetryCount === 1 ? 'y' : 'ies') + ', the operation is auto-rejected but the state stays ' +
          'manually away. Only an explicit manual switch to online restores normal behavior. ' +
          'Prefer work that does not depend on human input.'
      }
      return 'User attention: away (暂离). The user has not touched the DSH Web interface for a while. ' +
        'Human interactions are delivered with reminders; if no answer arrives after ' + cfg.awayRetryCount +
        ' retr' + (cfg.awayRetryCount === 1 ? 'y' : 'ies') + ', the operation is auto-rejected and the state becomes offline. ' +
        'Prefer work that does not depend on human input.'
    }
    return 'User attention: online (在线). The user is present at the DSH Web interface; approval prompts and ' +
      'ask_user_question are delivered normally. The state becomes away after ' + Math.round(cfg.idleTimeoutMs / 1000) +
      ' seconds without mouse or keyboard activity.'
  }

  // 冷启动时 systemPrompt / connection / timer 可能还没有就绪。一次性 ctx.get 会拿到
  // undefined 并静默跳过注册（浏览器里热安装时服务早已就绪，只有冷启动会暴露）。
  // 用 ctx.inject 把注册 park 到服务出现之后，与官方 approval / sandbox-policy 插件一致。
  try {
    ctx.inject(['systemPrompt'], (scope) => {
      try {
        const systemPrompt = scope.get('systemPrompt')
        if (systemPrompt === undefined || typeof systemPrompt.context !== 'function') return
        scope.effect(() => systemPrompt.context({
          name: 'user-attention',
          order: 118,
          text: () => attentionPromptText(),
        }), 'user-attention: prompt context')
      } catch (error) {
        log('prompt context registration failed:', error && error.message)
      }
    })
  } catch (error) {
    log('prompt context injection failed:', error && error.message)
  }

  // ---------------------------------------------------------------------------
  // 向 AI 说明（可回放的 user 消息；conversation 会按注入上下文渲染）
  // ---------------------------------------------------------------------------
  function resolveAgent(req) {
    const candidate = req !== null && typeof req === 'object' ? req.agent : undefined
    if (candidate === undefined || candidate === null) return undefined
    if (typeof candidate.inject === 'function') return candidate
    try {
      const agents = ctx.get('agents')
      if (agents !== undefined && typeof agents.get === 'function') return agents.get(candidate.id)
    } catch (error) { /* 无法解析就放弃注入 */ }
    return undefined
  }

  function explanationText(kind, reason) {
    const label = normalizeKind(kind) === 'question' ? 'question (ask_user_question)' : 'approval'
    if (reason === 'manual') {
      return 'Policy notice from user-attention: the user switched their attention state to offline, so this ' +
        label + ' request was auto-rejected. Do not retry human interactions while the user is offline; continue ' +
        'with work that needs no human input and mention in your reply what needs the user when they return.'
    }
    if (reason === 'timeout-manual') {
      return 'Policy notice from user-attention: the user is manually away and did not respond to this ' + label +
        ' request after ' + cfg.awayRetryCount + ' reminder(s), so it was auto-rejected. The attention state stays ' +
        'manually away (sticky, no auto-downgrade). Do not retry human interactions; continue with work that needs no ' +
        'human input, and mention in your reply what needs the user when they switch back to online.'
    }
    if (reason === 'timeout') {
      if (cfg.awayRetryCount === 0) {
        return 'Policy notice from user-attention: the user is away and retries are disabled (awayRetryCount is 0), so this ' +
          label + ' request was auto-rejected and the attention state is now offline. Do not retry human interactions; ' +
          'continue with work that needs no human input, and mention in your reply what the user needs to decide when they return.'
      }
      return 'Policy notice from user-attention: the user is away and did not respond to this ' + label +
        ' request after ' + cfg.awayRetryCount + ' reminder(s), so it was auto-rejected and the attention state is now ' +
        'offline. Do not retry human interactions; continue with work that needs no human input, and mention in your ' +
        'reply what the user needs to decide when they return.'
    }
    return 'Policy notice from user-attention: the user is offline, so human interactions are auto-rejected. ' +
      'This ' + label + ' request was rejected. Do not retry human interactions; continue with work that needs no ' +
      'human input, and mention in your reply what needs the user when they return.'
  }

  function explainToModel(kind, req, reason) {
    const agent = resolveAgent(req)
    if (agent === undefined) return
    const reasonLabel = reason === 'manual'
      ? '手动离线'
      : reason === 'timeout-manual'
        ? '手动暂离无响应'
        : reason === 'timeout'
          ? '暂离无响应'
          : '离线'
    let text = explanationText(kind, reason)
    // 待办收件箱已安装且自动入队开启时，告诉模型这次决策并没有消失：
    // 用户返回后可在待办里批准/回答，再通过 todo_execute 取回。
    if (todoInboxKeepsRejections()) {
      text += normalizeKind(kind) === 'question'
        ? ' A todo inbox is installed and auto-enqueue is on: this rejected question is kept there; ' +
          'after the user answers it, call todo_execute with its id to retrieve the answers — do not re-ask the question yourself.'
        : ' A todo inbox is installed and auto-enqueue is on: this rejected approval is kept there; ' +
          'after the user approves it, call todo_execute with its id to run the original call once — do not retry the approval before the user decides.'
    }
    try {
      agent.inject({
        role: 'user',
        id: uuid(),
        content: [{ type: 'text', text }],
        source: {
          kind: 'user-attention',
          form: 'notice',
          summary: '用户注意力：' + (normalizeKind(kind) === 'question' ? '提问' : '批准') + '请求已被自动拒绝（' +
            reasonLabel + '）',
        },
      })
    } catch (error) {
      log('inject explanation failed:', error && error.message)
    }
  }

  /** 待办收件箱是否真的会保留这次拒绝（服务存在且自动入队开启）。 */
  function todoInboxKeepsRejections() {
    try {
      const inbox = ctx.get('todoInbox')
      if (inbox === null || inbox === undefined || typeof inbox !== 'object') return false
      if (typeof inbox.takeApprovalGrant !== 'function') return false
      if (typeof inbox.autoEnqueueEnabled === 'function' && inbox.autoEnqueueEnabled() !== true) return false
      return true
    } catch (error) {
      return false
    }
  }

  // ---------------------------------------------------------------------------
  // 门控工具
  // ---------------------------------------------------------------------------
  function questionAbortedError() {
    const error = new Error('ask_user_question was aborted before the user answered')
    error.name = 'UserQuestionError'
    error.code = 'ASK_ABORTED'
    return error
  }

  function questionRejectedError(kind, reason) {
    const error = new Error(explanationText(kind, reason))
    error.name = 'UserQuestionError'
    error.code = 'USER_ATTENTION_REJECTED'
    return error
  }

  /** abort 时 approval 以 cancelled 收尾，提问以 ASK_ABORTED 抛出。 */
  function abortResult(kind) {
    if (normalizeKind(kind) === 'approval') return 'cancelled'
    throw questionAbortedError()
  }

  /** 最终拒绝：approval 返回 rejected，提问抛错（ask_user_question 会把错误显示给模型）。 */
  function finalReject(kind, reason) {
    if (normalizeKind(kind) === 'approval') return 'rejected'
    throw questionRejectedError(kind, reason)
  }

  /** 读取当前请求所属的会话 id（网关分发时通常 req.agent 已带上；缺失时回退 initiator）。 */
  function currentAgentId() {
    try {
      const agents = ctx.get('agents')
      if (agents === null || agents === undefined || typeof agents.currentInitiator !== 'function') return undefined
      const agent = agents.currentInitiator()
      return agent !== null && agent !== undefined && agent.id !== undefined ? String(agent.id) : undefined
    } catch (error) {
      return undefined
    }
  }

  /** 通知 userAttention 订阅者：一次最终拒绝已经发生（待办收件箱在此入队）。 */
  function emitRejection(kind, req, reason) {
    let event
    try {
      event = buildAttentionRejection(kind, req, reason, currentAgentId())
    } catch (error) {
      log('could not build rejection event:', error && error.message)
      return
    }
    // 超时策略为“拒绝”时不入队；非超时的最终拒绝保持原有全部入队行为。
    event.enqueue = timeoutEnqueueDecision(kind, reason)
    for (const listener of [...rejectionListeners]) {
      try {
        listener(event)
      } catch (error) {
        log('rejection listener failed:', error && error.message)
      }
    }
  }

  function timeoutEnqueueDecision(kind, reason) {
    if (reason !== 'timeout' && reason !== 'timeout-manual') return true
    return normalizeKind(kind) === 'approval'
      ? cfg.approvalTimeoutAction === 'enqueue'
      : cfg.questionTimeoutAction === 'enqueue'
  }

  /**
   * 所有最终拒绝的统一收尾：浏览器提醒、给模型的可回放说明、通知订阅者、
   * 然后把拒绝结果返回/抛出。集中到一处保证事件与拒绝行为一一对应。
   *
   * 提问超时且启用“按推荐选项”时，若批次里每个问题都有推荐项，则直接返回
   * 推荐答案（不进入拒绝/待办）；任一批次缺推荐项则退化为正常拒绝+入队。
   */
  function finalizeRejection(kind, req, reason) {
    const recommended = recommendedTimeoutAnswer(kind, req, reason)
    if (recommended !== null) {
      log('auto-answered timed-out question with recommended option(s)')
      return recommended
    }
    publishRejectedAlert(kind, reason)
    explainToModel(kind, req, reason)
    emitRejection(kind, req, reason)
    return finalReject(kind, reason)
  }

  function recommendedTimeoutAnswer(kind, req, reason) {
    if (normalizeKind(kind) !== 'question') return null
    if (cfg.preferRecommended !== true) return null
    if (reason !== 'timeout' && reason !== 'timeout-manual') return null
    try {
      return buildRecommendedAnswer(req !== null && typeof req === 'object' ? req.questions : undefined)
    } catch (error) {
      log('could not build recommended answer:', error && error.message)
      return null
    }
  }

  /**
   * 待办收件箱的一次性 approval grant：`todo_execute` 执行原工具前登记新
   * callId，注意力门控在这里消费它并直接放行，避免用户批准后又被拦一次。
   * 服务不存在（未安装待办插件）时返回 false，行为与之前完全一致。
   */
  function takeTodoGrant(callId) {
    if (callId === undefined || callId === null) return false
    try {
      const inbox = ctx.get('todoInbox')
      if (inbox === null || inbox === undefined || typeof inbox.takeApprovalGrant !== 'function') return false
      return inbox.takeApprovalGrant(String(callId)) === true
    } catch (error) {
      log('todo grant check failed:', error && error.message)
      return false
    }
  }

  /**
   * 等待「人类交互有结果 / 到下一次提醒 / 被中断 / 被门控唤醒」之一。
   * @param pending 已 tag 化的 next() 结果 promise。
   * @param timeoutMs 本次等待上限；null 表示只等结果或中断。
   */
  async function raceGate(pending, timeoutMs, signal, controller) {
    let timerId
    let onAbort
    const racers = [pending, controller.promise]
    if (timeoutMs !== null) {
      racers.push(new Promise((resolve) => {
        timerId = setTimeout(() => resolve({ type: 'timeout' }), timeoutMs)
      }))
    }
    if (signal !== undefined && signal !== null) {
      racers.push(new Promise((resolve) => {
        if (signal.aborted) { resolve({ type: 'abort' }); return }
        onAbort = () => resolve({ type: 'abort' })
        signal.addEventListener('abort', onAbort, { once: true })
      }))
    }
    try {
      return await Promise.race(racers)
    } finally {
      if (timerId !== undefined) clearTimeout(timerId)
      if (onAbort !== undefined) {
        try { signal.removeEventListener('abort', onAbort) } catch (error) { /* 已释放 */ }
      }
    }
  }

  function createGateController() {
    const controller = {
      settled: false,
      resolve: null,
      promise: null,
    }
    controller.promise = new Promise((resolve) => { controller.resolve = resolve })
    controller.wake = (tag) => {
      if (controller.settled) return
      controller.settled = true
      controller.resolve({ type: 'wake', tag })
    }
    return controller
  }

  /**
   * 呈现一次交互，并允许在超时/切换状态后把它从浏览器界面撤回。
   *
   * next() 会把请求转发给浏览器端（api-gateway 通过 request.signal 跟踪这次提问的生命周期：
   * signal 一旦 abort，就会给页面发 cancel 帧，审批卡片/提问卡片随之消失）。因此这里把
   * req.signal 换成 original + 本插件控制器的组合信号再调用 next()；撤回时 abort 自己的控制器。
   * 结束后恢复原来的 signal，避免影响宿主后续对 request 的读取。
   */
  function presentWithdrawable(req, next) {
    const originalSignal = req !== null && typeof req === 'object' ? req.signal : undefined
    let controller = null
    let mutable = false
    try {
      controller = new AbortController()
      const combined = originalSignal !== undefined && originalSignal !== null &&
        typeof AbortSignal !== 'undefined' && typeof AbortSignal.any === 'function'
        ? AbortSignal.any([originalSignal, controller.signal])
        : controller.signal
      if (req !== null && typeof req === 'object') {
        req.signal = combined
        mutable = true
      }
    } catch (error) {
      controller = null
      try { if (req !== null && typeof req === 'object') req.signal = originalSignal } catch (ignored) { /* frozen */ }
      log('could not wrap the forwarded request signal:', error && error.message)
    }
    const pending = Promise.resolve().then(() => next()).then(
      (value) => ({ type: 'value', value }),
      (error) => ({ type: 'error', error }),
    )
    return {
      pending,
      /** 让浏览器端撤下已呈现的交互（abort 组合信号 -> gateway 发 cancel 帧）。 */
      withdraw(reason) {
        if (controller === null) return
        try {
          controller.abort(reason instanceof Error ? reason : new Error('user-attention: interaction withdrawn'))
        } catch (error) { /* 已经撤回 */ }
      },
      /** 恢复请求原本的 signal（在 await 结束后调用）。 */
      restore() {
        if (!mutable) return
        try { req.signal = originalSignal } catch (error) { /* frozen */ }
      },
    }
  }

  /**
   * 状态驱动的交互门控（A.6）。交互照常呈现给用户，但插件在后台按真实注意力
   * 状态决定何时提醒、何时最终拒绝：
   *
   *   online  — 普通等待；每 awayRetryIntervalMs 复查一次状态。等待中变成 away
   *             时把 attempt 归零，重新进入提醒预算。
   *   away    — 保持原有 attempt/maxAttempts 语义：超时提醒，重试耗尽后拒绝；
   *             再次回到 online 就切回普通等待（不撤回已呈现的交互）。
   *   offline — 立即拒绝（在呈现之前处理，不记录为等待中的交互）。
   *
   * 手动 away 是粘性的：耗尽后只拒绝本次交互，不自动转 offline。
   * 只有最终拒绝才调用 explainToModel；状态切换和重提醒都不向模型注入消息。
   */
  async function attentionGate(kind, req, next) {
    const signal = req !== null && typeof req === 'object' ? req.signal : undefined
    if (signal !== undefined && signal !== null && signal.aborted) return abortResult(kind)

    // offline：立即拒绝，不做呈现、不占用 activeInteractions。
    if (state === 'offline') {
      return finalizeRejection(kind, req, 'offline')
    }

    // awayRetryCount: 0 —— 保持现有行为：不呈现、不等待，直接按「无响应」拒绝。
    const maxAttempts = cfg.awayRetryCount + 1
    if (state === 'away' && maxAttempts <= 1) {
      if (manualState) {
        // 手动暂离的粘性优先：只拒绝本次交互，不自动降级为离线。
        return finalizeRejection(kind, req, 'timeout-manual')
      }
      setState('offline', 'away with no retries and ' + normalizeKind(kind) + ' interaction')
      return finalizeRejection(kind, req, 'timeout')
    }

    // 从这里开始交互会被呈现给浏览器；记录它，直到门控结束（含异常路径）。
    const interaction = { kind: normalizeKind(kind), at: Date.now() }
    activeInteractions.add(interaction)
    return await presentedGate(kind, req, next, signal, maxAttempts).finally(() => {
      activeInteractions.delete(interaction)
    })
  }

  /** 呈现交互并跑状态驱动循环；调用方负责 activeInteractions 记账。 */
  async function presentedGate(kind, req, next, signal, maxAttempts) {
    const controller = createGateController()
    activeGates.add(controller)
    const presented = presentWithdrawable(req, next)
    const pending = presented.pending
    // 从 away 进入门控时已经处在第一轮等待；从 online 进入时预算尚未使用。
    let attempt = state === 'away' ? 1 : 0

    try {
      while (true) {
        const outcome = await raceGate(pending, cfg.awayRetryIntervalMs, signal, controller)
        if (outcome.type === 'value') return outcome.value
        if (outcome.type === 'error') throw outcome.error
        if (outcome.type === 'abort') {
          presented.withdraw(new Error('user-attention: interaction was aborted'))
          return abortResult(kind)
        }
        if (outcome.type === 'wake') {
          if (outcome.tag === 'cancel') {
            presented.withdraw(new Error('user-attention: interaction was cancelled'))
            return abortResult(kind)
          }
          // 手动切到离线：立即拒绝未处理的交互（并撤下已呈现的界面）。
          if (outcome.tag === 'manual-offline') {
            presented.withdraw(new Error('user-attention: user switched to offline'))
            return finalizeRejection(kind, req, 'manual')
          }
          continue
        }

        // 本轮等待超时，按当前真实状态决定下一步。
        if (state === 'online') {
          // 已回到在线：切回普通等待，不撤回已呈现的交互。
          attempt = 0
          continue
        }

        if (state === 'offline') {
          presented.withdraw(new Error('user-attention: user is offline'))
          return finalizeRejection(kind, req, 'offline')
        }

        // state === 'away'
        if (attempt === 0) {
          // 等待期间从 online 变成 away：重新进入提醒预算，按 away 的原有节奏
          // 先等待一个间隔；重试关闭（maxAttempts <= 1）则本次直接拒绝。
          attempt = 1
          if (attempt < maxAttempts) continue
        }

        if (attempt >= maxAttempts) {
          // 手动暂离是粘性的：只拒绝本次交互，不自动降级为离线，直到手动切回在线。
          if (manualState) {
            presented.withdraw(new Error('user-attention: manual away timed out'))
            return finalizeRejection(kind, req, 'timeout-manual')
          }
          presented.withdraw(new Error('user-attention: away retries exhausted'))
          setState('offline', 'no response to ' + normalizeKind(kind) + ' interaction')
          return finalizeRejection(kind, req, 'timeout')
        }

        attempt += 1
        publishRetryAlert(kind, attempt, maxAttempts)
      }
    } finally {
      presented.restore()
      activeGates.delete(controller)
      controller.settled = true
    }
  }

  // ---------------------------------------------------------------------------
  // 人类交互门控（approval / ask_user_question）
  // ---------------------------------------------------------------------------
  /**
   * 在线期间由官方 UI 正常呈现的交互：只记账（供配置保存保护），不改变官方
   * 超时/撤回语义。当前实现不把在线投递纳入注意力监督，该语义留给后续版本。
   */
  function trackOnlineInteraction(kind, next) {
    const interaction = { kind: normalizeKind(kind), at: Date.now() }
    activeInteractions.add(interaction)
    return Promise.resolve()
      .then(() => next())
      .finally(() => {
        activeInteractions.delete(interaction)
      })
  }

  function handleApproval(req, next) {
    // 待办收件箱的一次性执行授权必须先于在线/离线判断：用户已经在待办里
    // 批准过这次执行，不能让他再看到第二张审批卡，也不能被离线门控拦下。
    const callId = req !== null && typeof req === 'object' ? req.callId : undefined
    if (takeTodoGrant(callId)) {
      log('approval allowed once by a todo-inbox grant:', callId === undefined ? '(no callId)' : String(callId))
      return Promise.resolve('allowed-once')
    }
    if (state === 'online') return trackOnlineInteraction('approval', next)
    return attentionGate('approval', req, next)
  }

  function handleQuestion(req, next) {
    if (state === 'online') return trackOnlineInteraction('question', next)
    return attentionGate('question', req, next)
  }

  try {
    ctx.on('approval/request', (req, next) => handleApproval(req, next), { prepend: true })
    ctx.on('user-questions/request', (req, next) => handleQuestion(req, next), { prepend: true })
  } catch (error) {
    log('waterfall listener registration failed:', error && error.message)
  }

  // ---------------------------------------------------------------------------
  // 空闲看门狗：online 超过 idleTimeoutMs 无活动 -> away
  // ---------------------------------------------------------------------------
  function tick() {
    if (disposed) return
    if (state === 'online' && Date.now() - lastActivityAt >= cfg.idleTimeoutMs) {
      setState('away', 'idle for ' + cfg.idleTimeoutMs + 'ms')
    }
  }
  function startWatchdog(scope) {
    try {
      const timer = scope.get('timer')
      if (timer !== undefined && typeof timer.interval === 'function') {
        scope.effect(() => timer.interval(tick, cfg.tickMs), 'user-attention: idle watchdog')
      } else {
        const id = setInterval(tick, cfg.tickMs)
        scope.effect(() => () => clearInterval(id), 'user-attention: idle watchdog (fallback)')
      }
    } catch (error) {
      log('idle watchdog registration failed:', error && error.message)
    }
  }
  try {
    ctx.inject(['timer'], startWatchdog)
  } catch (error) {
    log('idle watchdog injection failed:', error && error.message)
  }

  // ---------------------------------------------------------------------------
  // 浏览器侧 HTTP 路由（与页面同源、经应用鉴权栅栏）
  // ---------------------------------------------------------------------------
  async function readJsonBody(request) {
    try {
      const parsed = await request.json()
      return parsed !== null && typeof parsed === 'object' ? parsed : {}
    } catch (error) {
      return {}
    }
  }

  /**
   * 定位本插件的 profile 配置行：优先 options.name，回退 options.id（A.3）。
   * GET 与 POST 共用，避免两条路径的定位规则漂移。
   */
  function findConfigTarget() {
    return findTargetByNames('@local/dsh-user-attention-core', 'user-attention')
  }

  /** 同一 bundle 里的待办组件行；bundle 配置页保存 autoEnqueue 时一并写回。 */
  function findTodoConfigTarget() {
    return findTargetByNames('@local/dsh-todo-inbox', 'todo-inbox')
  }

  function findTargetByNames(name, id) {
    let editor
    try {
      editor = ctx.get('configEditor')
    } catch (error) {
      editor = undefined
    }
    if (editor === undefined || editor === null || typeof editor.entries !== 'function') {
      return { editor: undefined, entry: undefined }
    }
    let rows = []
    try {
      rows = editor.entries()
    } catch (error) {
      rows = []
    }
    const list = Array.isArray(rows) ? rows : []
    const usable = (row) => row !== null && typeof row === 'object' &&
      row.options !== null && typeof row.options === 'object'
    const entry = list.find((row) => usable(row) && row.options.name === name) ||
      list.find((row) => usable(row) && row.options.id === id)
    return { editor, entry }
  }

  function registerRoutes(scope) {
    const connection = scope.get('connection')
    if (connection === undefined || connection.fetch === undefined || typeof connection.fetch.register !== 'function') {
      log('connection.fetch unavailable; routes not registered')
      return
    }
    const routeRegister = (route, label) => {
      try {
        scope.effect(() => connection.fetch.register(route), label)
      } catch (error) {
        log('route registration failed:', label, error && error.message)
      }
    }

  routeRegister({
    path: '/api/user-attention/state',
    methods: ['GET'],
    requestBody: 'buffered',
    fetch: async () => {
      try {
        return jsonResponse(statePayload())
      } catch (error) {
        return jsonResponse({ ok: false, error: String((error && error.message) || error) }, 500)
      }
    },
  }, 'user-attention: state route')

  routeRegister({
    path: '/api/user-attention/ack',
    methods: ['POST'],
    requestBody: 'buffered',
    fetch: async (request) => {
      try {
        const body = await readJsonBody(request)
        const upto = body.upto
        if (typeof upto !== 'number' || !Number.isSafeInteger(upto) || upto < 0) {
          return jsonResponse({ ok: false, error: 'upto must be a non-negative safe integer' }, 400)
        }
        ackedThrough = Math.max(ackedThrough, Math.min(upto, rejectionSeq))
        if (rejections.length > 0) {
          rejections = rejections.filter((item) => item.seq > ackedThrough)
        }
        return jsonResponse({ ok: true, rejections: rejectionsPayload() })
      } catch (error) {
        return jsonResponse({ ok: false, error: String((error && error.message) || error) }, 500)
      }
    },
  }, 'user-attention: ack route')

  routeRegister({
    path: '/api/user-attention/activity',
    methods: ['POST'],
    requestBody: 'buffered',
    fetch: async (request) => {
      try {
        const body = await readJsonBody(request)
        const kind = typeof body.kind === 'string' ? body.kind : ''
        if (!ACTIVITY_KINDS.has(kind)) {
          return jsonResponse({ ok: false, error: 'kind must be one of ' + Array.from(ACTIVITY_KINDS).join('|') }, 400)
        }
        noteActivity(kind)
        return jsonResponse({ ok: true, state, manual: manualState, lastActivityAt, alertSeq })
      } catch (error) {
        return jsonResponse({ ok: false, error: String((error && error.message) || error) }, 500)
      }
    },
  }, 'user-attention: activity route')

  routeRegister({
    path: '/api/user-attention/set',
    methods: ['POST'],
    requestBody: 'buffered',
    fetch: async (request) => {
      try {
        const body = await readJsonBody(request)
        const next = typeof body.state === 'string' ? body.state : undefined
        if (next === undefined || !STATES.includes(next)) {
          return jsonResponse({ ok: false, error: 'state must be one of ' + STATES.join('|') }, 400)
        }
        if (next === 'online') lastActivityAt = Date.now()
        // next 非在线 = 人类主动选择的「粘性」状态：冻结自动状态机直到手动切回在线。
        manualState = next !== 'online'
        const previousState = state
        setState(next, 'manual')
        // 状态没变（例如自动暂离后又被手动设为暂离）时 setState 不会发通知，
        // 但 manual 标记已改变，订阅者仍需要知道。
        if (previousState === state) notifyState(previousState, 'manual')
        // 手动状态跨重载/重启（A.5）：先完成状态切换，写盘失败只记日志。
        if (next === 'online') clearPersistedManualState()
        else persistManualState(next)
        if (next === 'offline') {
          for (const controller of activeGates) controller.wake('manual-offline')
        }
        return jsonResponse({ ok: true, state, manual: manualState })
      } catch (error) {
        return jsonResponse({ ok: false, error: String((error && error.message) || error) }, 500)
      }
    },
  }, 'user-attention: set route')

  routeRegister({
    path: '/api/user-attention/config',
    methods: ['GET', 'POST'],
    requestBody: 'buffered',
    fetch: async (request) => {
      try {
        const target = findConfigTarget()
        const editor = target.editor
        const entry = target.entry
        if (request.method === 'POST') {
          const body = await readJsonBody(request)
          // A.3：还有已呈现但未结束的人工交互时，保存配置会取消它们，必须显式 force。
          if (activeInteractions.size > 0 && body.force !== true) {
            return jsonResponse({
              ok: false,
              code: 'PENDING_INTERACTIONS',
              pending: activeInteractions.size,
              error: '还有 ' + activeInteractions.size + ' 个人工交互正在等待处理；保存配置会取消它们。确认后以 force:true 重试。',
            }, 409)
          }
          const patch = {}
          if (body.idleTimeoutMs !== undefined) {
            const idle = body.idleTimeoutMs
            // 只接受真正的安全整数（拒绝 "5000"、["5000"]、12.5 等隐式强转输入）。
            if (typeof idle !== 'number' || !Number.isSafeInteger(idle) || idle < 1000 || idle > 24 * 3600 * 1000) {
              return jsonResponse({ ok: false, error: 'idleTimeoutMs must be an integer between 1000 and 86400000' }, 400)
            }
            patch.idleTimeoutMs = idle
          }
          if (body.awayRetryCount !== undefined) {
            const retries = body.awayRetryCount
            if (typeof retries !== 'number' || !Number.isSafeInteger(retries) || retries < 0 || retries > 5) {
              return jsonResponse({ ok: false, error: 'awayRetryCount must be an integer between 0 and 5' }, 400)
            }
            patch.awayRetryCount = retries
          }
          if (body.persistManualState !== undefined) {
            if (typeof body.persistManualState !== 'boolean') {
              return jsonResponse({ ok: false, error: 'persistManualState must be a boolean' }, 400)
            }
            patch.persistManualState = body.persistManualState
          }
          if (body.approvalTimeoutAction !== undefined) {
            if (!TIMEOUT_ACTIONS.includes(body.approvalTimeoutAction)) {
              return jsonResponse({ ok: false, error: 'approvalTimeoutAction must be reject|enqueue' }, 400)
            }
            patch.approvalTimeoutAction = body.approvalTimeoutAction
          }
          if (body.questionTimeoutAction !== undefined) {
            if (!TIMEOUT_ACTIONS.includes(body.questionTimeoutAction)) {
              return jsonResponse({ ok: false, error: 'questionTimeoutAction must be reject|enqueue' }, 400)
            }
            patch.questionTimeoutAction = body.questionTimeoutAction
          }
          if (body.preferRecommended !== undefined) {
            if (typeof body.preferRecommended !== 'boolean') {
              return jsonResponse({ ok: false, error: 'preferRecommended must be a boolean' }, 400)
            }
            patch.preferRecommended = body.preferRecommended
          }
          if (body.todoAutoEnqueue !== undefined) {
            if (typeof body.todoAutoEnqueue !== 'boolean') {
              return jsonResponse({ ok: false, error: 'todoAutoEnqueue must be a boolean' }, 400)
            }
            patch.todoAutoEnqueue = body.todoAutoEnqueue
          }
          if (Object.keys(patch).length === 0) {
            return jsonResponse({
              ok: false,
              error: 'provide idleTimeoutMs, awayRetryCount, persistManualState, approvalTimeoutAction, questionTimeoutAction, preferRecommended and/or todoAutoEnqueue',
            }, 400)
          }
          if (editor === undefined || typeof editor.edit !== 'function' || entry === undefined) {
            return jsonResponse({ ok: false, error: '当前 profile 不支持写回注意力组件配置（configEditor 或配置行不可用）' }, 409)
          }
          // 写回 profile 补丁里本行的 config；Loader 随后重新激活本插件。
          try {
            await editor.edit(entry, (current) => Object.assign({}, current, patch))
          } catch (error) {
            log('config write failed:', error && error.message)
            return jsonResponse({ ok: false, error: '写入配置失败：' + String((error && error.message) || error) }, 500)
          }
          // 读回写后的整行原始 config（edit 完成后 Loader 已完成 reconcile）；未在本次
          // patch 中的字段用读回值或当前生效值回填。
          let merged = null
          try {
            const after = findConfigTarget()
            if (after.entry !== undefined && after.entry.options !== undefined &&
              after.entry.options.config !== null && typeof after.entry.options.config === 'object') {
              merged = after.entry.options.config
            }
          } catch (error) { /* 读回失败时回退到当前生效配置 */ }
          return jsonResponse({
            ok: true,
            idleTimeoutMs: patch.idleTimeoutMs !== undefined
              ? patch.idleTimeoutMs
              : (merged !== null && typeof merged.idleTimeoutMs === 'number' ? merged.idleTimeoutMs : cfg.idleTimeoutMs),
            awayRetryCount: patch.awayRetryCount !== undefined
              ? patch.awayRetryCount
              : (merged !== null && typeof merged.awayRetryCount === 'number' ? merged.awayRetryCount : cfg.awayRetryCount),
            persistManualState: patch.persistManualState !== undefined
              ? patch.persistManualState
              : (merged !== null && typeof merged.persistManualState === 'boolean' ? merged.persistManualState : cfg.persistManualState),
            approvalTimeoutAction: patch.approvalTimeoutAction !== undefined
              ? patch.approvalTimeoutAction
              : (merged !== null && TIMEOUT_ACTIONS.includes(merged.approvalTimeoutAction) ? merged.approvalTimeoutAction : cfg.approvalTimeoutAction),
            questionTimeoutAction: patch.questionTimeoutAction !== undefined
              ? patch.questionTimeoutAction
              : (merged !== null && TIMEOUT_ACTIONS.includes(merged.questionTimeoutAction) ? merged.questionTimeoutAction : cfg.questionTimeoutAction),
            preferRecommended: patch.preferRecommended !== undefined
              ? patch.preferRecommended
              : (merged !== null && typeof merged.preferRecommended === 'boolean' ? merged.preferRecommended : cfg.preferRecommended),
            todoAutoEnqueue: patch.todoAutoEnqueue !== undefined
              ? patch.todoAutoEnqueue
              : (merged !== null && typeof merged.todoAutoEnqueue === 'boolean' ? merged.todoAutoEnqueue : cfg.todoAutoEnqueue),
          })
        }
        let todo = null
        try { todo = ctx.get('todoInbox') } catch (error) { todo = null }
        const todoAvailable = todo !== null && todo !== undefined && typeof todo.takeApprovalGrant === 'function'
        const todoEnabled = cfg.todoAutoEnqueue === true
        return jsonResponse({
          ok: true,
          idleTimeoutMs: cfg.idleTimeoutMs,
          awayRetryCount: cfg.awayRetryCount,
          awayRetryIntervalMs: cfg.awayRetryIntervalMs,
          tickMs: cfg.tickMs,
          pollIntervalMs: cfg.pollIntervalMs,
          initialState: cfg.initialState,
          persistManualState: cfg.persistManualState,
          approvalTimeoutAction: cfg.approvalTimeoutAction,
          questionTimeoutAction: cfg.questionTimeoutAction,
          preferRecommended: cfg.preferRecommended,
          todoAutoEnqueue: cfg.todoAutoEnqueue,
          todoAvailable,
          todoEnabled,
          writable: editor !== undefined && typeof editor.edit === 'function' && entry !== undefined,
        })
      } catch (error) {
        return jsonResponse({ ok: false, error: String((error && error.message) || error) }, 500)
      }
    },
  }, 'user-attention: config route')
  }

  try {
    ctx.inject(['connection'], registerRoutes)
  } catch (error) {
    log('route registration injection failed:', error && error.message)
  }

  // ---------------------------------------------------------------------------
  // Host service：userAttention
  //
  // 注意力插件对其他 Host 插件暴露的唯一稳定面：
  //   snapshot()          当前状态快照（只读）
  //   subscribe(fn)       状态变化通知（fn 收到 previous/state/manual/since/…）
  //   onRejection(fn)     每次「最终拒绝」一个 human interaction 时通知
  //
  // 待办收件箱通过 onRejection 自动入队；它提供的 todoInbox 服务则被本插件
  // 在审批门控前查询一次性执行授权。两者都用 ctx.get 懒查，任何一个插件缺失
  // 都不影响另一个加载。
  // ---------------------------------------------------------------------------
  function provideAttentionService() {
    if (typeof ctx.provide !== 'function') {
      log('ctx.provide unavailable; userAttention service not registered')
      return
    }
    const service = {
      version: ATTENTION_REJECTION_VERSION,
      snapshot() {
        return {
          state,
          manual: manualState,
          since,
          lastActivityAt,
          idleTimeoutMs: cfg.idleTimeoutMs,
          awayRetryCount: cfg.awayRetryCount,
        }
      },
      subscribe(listener) {
        if (typeof listener !== 'function') return () => {}
        stateListeners.add(listener)
        return () => { stateListeners.delete(listener) }
      },
      onRejection(listener) {
        if (typeof listener !== 'function') return () => {}
        rejectionListeners.add(listener)
        return () => { rejectionListeners.delete(listener) }
      },
      /** 供待办组件读取 bundle 配置页里的自动入队开关。 */
      todoAutoEnqueue() {
        return cfg.todoAutoEnqueue === true
      },
    }
    try {
      ctx.effect(() => ctx.provide('userAttention', service), 'user-attention: host service')
      log('userAttention Host service registered')
    } catch (error) {
      log('could not register the userAttention Host service:', error && error.message)
    }
  }
  provideAttentionService()

  // ---------------------------------------------------------------------------
  // 卸载清理：收尾还在等待的门控，避免悬挂
  // ---------------------------------------------------------------------------
  ctx.effect(() => () => {
    disposed = true
    for (const controller of activeGates) controller.wake('cancel')
    activeGates.clear()
    activeInteractions.clear()
    stateListeners.clear()
    rejectionListeners.clear()
  }, 'user-attention: pending gates cleanup')

  log('host active — state=' + state + ', idleTimeoutMs=' + cfg.idleTimeoutMs + ', retries=' + cfg.awayRetryCount)
}
